from pathlib import Path
import csv
import base64
import sys
import json

CSV_DATEI = Path("reime.csv")
AUSGABE_DATEI = Path("index.html")
VERSION = "2.48"

# WICHTIG:
# Diese Schablone ist die aktuelle vollständige Reimfinder-Seite.
# Beim Aktualisieren der Reimwörter wird ausschließlich der Datenblock
# aus reime.csv ersetzt. Gestaltung, Google-Texte, Popup, Mobilansicht,
# "nach oben"-Funktion, die Abschnitte unten, der neue Qualitäts-Hinweis sowie die Gestaltung ohne doppelte Hauptüberschrift
# bleiben dadurch erhalten.
HTML_TEMPLATE_B64 = ''


def lese_reime():
    if not CSV_DATEI.exists():
        print("Fehler: reime.csv wurde nicht gefunden.")
        sys.exit(1)

    gruppen = []
    with CSV_DATEI.open("r", encoding="utf-8-sig", newline="") as f:
        reader = csv.reader(f, delimiter=";")
        for zeilennummer, zeile in enumerate(reader, start=1):
            felder = [feld.strip() for feld in zeile if feld.strip()]
            if not felder:
                continue
            if len(felder) < 2:
                print(
                    f"Warnung: Zeile {zeilennummer} enthält keine "
                    "Reimwörter und wird ausgelassen."
                )
                continue
            gruppen.append(felder)

    if not gruppen:
        print("Fehler: In reime.csv wurden keine gültigen Reimgruppen gefunden.")
        sys.exit(1)

    return gruppen


def sichere_javascript_daten(text):
    return (
        text.replace("\\", "\\\\")
            .replace("`", "\\`")
            .replace("${", "\\${")
    )



ICON_192_B64 = ""
ICON_512_B64 = ""
ICON_512_MASKABLE_B64 = ""

def main():
    gruppen = lese_reime()
    daten = sichere_javascript_daten("\n".join(";".join(g) for g in gruppen))
    template = base64.b64decode(HTML_TEMPLATE_B64).decode("utf-8")
    if "__REIMDATEN__" not in template:
        print("Fehler: Datenplatzhalter fehlt."); sys.exit(1)
    website = template.replace("__REIMDATEN__", daten, 1)
    AUSGABE_DATEI.write_text(website, encoding="utf-8")

    import re, json
    local_bridge = """<script id="strato-search-bridge">
function starteStratoSuche(){searchRhymes();}
(function(){
 const feld=document.getElementById('searchInput');
 const knopf=document.querySelector('.btn-search');
 if(knopf)knopf.onclick=starteStratoSuche;
 if(feld)feld.addEventListener('keydown',function(event){
  if(event.key==='Enter'){event.preventDefault();starteStratoSuche();}
 });
})();
</script>"""
    app, count = re.subn(r'<script id="strato-search-bridge">.*?</script>',
                         lambda _: local_bridge, website, count=1, flags=re.S)
    if count != 1:
        print("Fehler: App-Suchfunktion konnte nicht angepasst werden."); sys.exit(1)
    Path("app.html").write_text(app, encoding="utf-8")

    manifest = {
      "id":"./app.html","name":"Online-Reimfinder von Faltsch Wagoni",
      "short_name":"Reimfinder",
      "description":"Deutsche Reime nach Klang und Betonung suchen – auch offline.",
      "lang":"de","start_url":"./app.html","scope":"./","display":"standalone",
      "orientation":"any","background_color":"#0f172a","theme_color":"#0f172a",
      "icons":[
        {"src":"./icons/icon-192.png","sizes":"192x192","type":"image/png","purpose":"any"},
        {"src":"./icons/icon-512.png","sizes":"512x512","type":"image/png","purpose":"any"},
        {"src":"./icons/icon-512-maskable.png","sizes":"512x512","type":"image/png","purpose":"maskable"}
      ]
    }
    Path("manifest.webmanifest").write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding="utf-8")

    cache_version = VERSION.replace(".","-")
    sw = (
      'const CACHE_NAME = "reimfinder-pwa-' + cache_version + '";\n'
      'const FILES = ["./","./index.html","./app.html","./manifest.webmanifest",'
      '"./icons/icon-192.png","./icons/icon-512.png","./icons/icon-512-maskable.png"];\n'
      'self.addEventListener("install",e=>e.waitUntil(caches.open(CACHE_NAME).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));\n'
      'self.addEventListener("activate",e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith("reimfinder-pwa-")&&k!==CACHE_NAME).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));\n'
      'self.addEventListener("fetch",e=>{const r=e.request;if(r.method!=="GET")return;const u=new URL(r.url);if(u.origin!==self.location.origin)return;'
      'if(r.mode==="navigate"){e.respondWith(fetch(r,{cache:"no-store"}).then(res=>{if(res&&res.ok){const cp=res.clone();caches.open(CACHE_NAME).then(c=>c.put(r,cp));}return res;}).catch(()=>caches.match(r).then(c=>c||caches.match("./app.html"))));return;}'
      'e.respondWith(caches.match(r).then(c=>c||fetch(r).then(res=>{if(res&&res.ok){const cp=res.clone();caches.open(CACHE_NAME).then(cache=>cache.put(r,cp));}return res;})));});\n'
    )
    Path("service-worker.js").write_text(sw,encoding="utf-8")

    icons=Path("icons");icons.mkdir(exist_ok=True)
    (icons/"icon-192.png").write_bytes(base64.b64decode(ICON_192_B64))
    (icons/"icon-512.png").write_bytes(base64.b64decode(ICON_512_B64))
    (icons/"icon-512-maskable.png").write_bytes(base64.b64decode(ICON_512_MASKABLE_B64))

    words=sum(len(g)-1 for g in gruppen)
    print("Fertig! Builder-Version:",VERSION)
    print("Erzeugt: index.html (Website), app.html (App), manifest.webmanifest, service-worker.js, icons/")
    print("Reimgruppen:",len(gruppen),"| Reimwörter:",words)
    print("Website-Suche übergibt an Strato; App-Suche bleibt lokal.")


if __name__ == "__main__":
    main()
